// checkHostInputRequestHostInputRequestValue checks one generated value on the active path.
func checkHostInputRequestHostInputRequestValue(in *HostInputRequest, field string, active map[any]bool) error {
	if in == nil {
		return nil
	}
	if active[in] {
		return fmt.Errorf("%s: cyclic Go value", field)
	}
	active[in] = true
	defer delete(active, in)
	if in != nil {
		if branch1, ok := in.Question.AsForm(); ok {
			_ = branch1
			if err := checkHostFormParamsHostFormParamsValue(branch1, generatedJSONChildPath(generatedJSONChildPath(field, "question", false), "value", false), active); err != nil {
				return err
			}
		}
		if branch1, ok := in.Question.AsURL(); ok {
			_ = branch1
			if err := checkHostInputRequestHostURLParamsValue(branch1, generatedJSONChildPath(generatedJSONChildPath(field, "question", false), "value", false), active); err != nil {
				return err
			}
		}
		for key1, item1 := range in.Extensions {
			_ = item1
			if !utf8.ValidString(string(key1)) {
				return fmt.Errorf("%s: invalid UTF-8 map key", generatedJSONChildPath(field, "extensions", false))
			}
		}
	}
	return nil
}

